const WORDS = ['FUTURE.', 'ENTERPRISE.', 'STARTUP.', 'LEGACY.', 'EMPIRE.'] as const
const STROKE_COLOR = '#6C1D7A'
const STAGGER_MS = 160
const STROKE_DURATION_MS = 300
const FILL_DURATION_MS = 380
const HOLD_MS = 1800
const TRANSITION_MS = 320

interface LetterPaths {
  stroke: SVGPathElement | null
  fill: SVGPathElement | null
}

function StrokeTypedText() {
  const svgRef = useRef<SVGSVGElement>(null)
  const wordIndexRef = useRef(0)
  // Track ALL active timer IDs so every one can be cancelled on cleanup/word change
  const timerIdsRef = useRef<ReturnType<typeof setTimeout>[]>([])

  const clearTimers = useCallback(() => {
    timerIdsRef.current.forEach(id => clearTimeout(id))
    timerIdsRef.current = []
  }, [])

  // Convenience: schedule a timeout and remember its ID
  const schedule = useCallback((fn: () => void, ms: number) => {
    const id = setTimeout(fn, ms)
    timerIdsRef.current.push(id)
    return id
  }, [])

  const buildLetterEls = useCallback((word: string): LetterPaths[] => {
    const svg = svgRef.current
    if (!svg) return []
    const wordData = WORD_PATHS[word]
    if (!wordData) return []

    while (svg.firstChild) svg.removeChild(svg.firstChild)

    svg.setAttribute('viewBox', '0 0 ' + wordData.totalWidth + ' ' + wordData.viewH)
    svg.removeAttribute('width')
    svg.removeAttribute('height')

    const pairs: LetterPaths[] = []

    for (const { d } of wordData.letters) {
      const fillEl = document.createElementNS('http://www.w3.org/2000/svg', 'path')
      fillEl.setAttribute('d', d)
      fillEl.setAttribute('fill', STROKE_COLOR)
      fillEl.setAttribute('stroke', 'none')
      fillEl.style.opacity = '0'
      fillEl.style.transition = 'opacity ' + FILL_DURATION_MS + 'ms ease-out'

      const strokeEl = document.createElementNS('http://www.w3.org/2000/svg', 'path')
      strokeEl.setAttribute('d', d)
      strokeEl.setAttribute('fill', 'none')
      strokeEl.setAttribute('stroke', STROKE_COLOR)
      strokeEl.setAttribute('stroke-width', '2.5')
      strokeEl.setAttribute('stroke-linecap', 'round')
      strokeEl.setAttribute('stroke-linejoin', 'round')
      strokeEl.style.opacity = '1'
      strokeEl.style.transition = 'opacity ' + TRANSITION_MS + 'ms ease-out'

      svg.appendChild(fillEl)
      svg.appendChild(strokeEl)
      pairs.push({ fill: fillEl, stroke: strokeEl })
    }

    return pairs
  }, [])

  const measureAndReset = useCallback((pairs: LetterPaths[]) => {
    for (const { stroke } of pairs) {
      if (!stroke) continue
      const len = stroke.getTotalLength()
      stroke.style.strokeDasharray = String(len)
      stroke.style.strokeDashoffset = String(len)
      stroke.style.transition = 'none'
    }
  }, [])

  const animateWord = useCallback((word: string) => {
    clearTimers()
    const pairs = buildLetterEls(word)
    if (!pairs.length) return

    requestAnimationFrame(() => {
      measureAndReset(pairs)

      // ── Phase 1: draw strokes letter by letter (staggered) ──
      pairs.forEach(({ stroke }, i) => {
        if (!stroke) return
        schedule(() => {
          stroke.style.transition = 'stroke-dashoffset ' + STROKE_DURATION_MS + 'ms ease-out'
          stroke.style.strokeDashoffset = '0'
        }, i * STAGGER_MS)
      })

      // When the last stroke finishes drawing
      const strokesDone = (pairs.length - 1) * STAGGER_MS + STROKE_DURATION_MS + 80

      // ── Phase 2: fade in fills (staggered), starting after all strokes drawn ──
      schedule(() => {
        pairs.forEach(({ fill }, i) => {
          if (!fill) return
          schedule(() => { fill.style.opacity = '1' }, i * 80)
        })
      }, strokesDone)

      // When the LAST fill letter finishes fading in
      const allFillsDone = strokesDone + (pairs.length - 1) * 80 + FILL_DURATION_MS

      // ── Phase 3: fade out strokes only AFTER all fills are fully visible ──
      schedule(() => {
        pairs.forEach(({ stroke }) => {
          if (!stroke) return
          stroke.style.opacity = '0'
        })
      }, allFillsDone)

      // ── Phase 4: hold, then fade out fills and cycle to next word ──
      schedule(() => {
        pairs.forEach(({ fill }) => {
          if (!fill) return
          fill.style.transition = 'opacity ' + TRANSITION_MS + 'ms ease-in'
          fill.style.opacity = '0'
        })
        schedule(() => {
          wordIndexRef.current = (wordIndexRef.current + 1) % WORDS.length
          animateWord(WORDS[wordIndexRef.current])
        }, TRANSITION_MS + 60)
      }, allFillsDone + HOLD_MS)
    })
  }, [buildLetterEls, measureAndReset, clearTimers, schedule])

  useEffect(() => {
    animateWord(WORDS[0])
    return () => clearTimers()
  }, [animateWord, clearTimers])

  return (
    <span className="hero-typed-wrapper" aria-label="animated word" aria-live="polite">
      <svg
        ref={svgRef}
        style={{
          display: 'inline-block',
          height: '1em',
          width: 'auto',
          maxWidth: 'none',
          overflow: 'visible',
          verticalAlign: 'baseline',
        }}
        aria-hidden="true"
      />
    </span>
  )
}

